def prewarm(tx: Transaction) -> None:
    execution_profile = kernel_environment.k_execution_profile
    profile = execution_profile.protocol
    k_account_mark_warm(tx.sender)
    if tx.is_create:
        pass
    else:
        k_account_mark_warm(tx.recipient)
    if (int(profile.fork) >= int(Shanghai)):
        coinbase = k_coinbase()
        k_account_mark_warm(coinbase)
    access_list = tx.access_list.encoded
    return warm_access_list(access_list)

def eff_gas_price_for(base_fee: word, max_fee: word, max_priority_fee: word) -> tuple[word, word]:
    max_fee_below_base = word_ule(max_fee, base_fee)
    if max_fee_below_base:
        price = max_fee
    else:
        available_priority = word_sub_word(max_fee, base_fee)
        priority_within_cap = word_ule(max_priority_fee, available_priority)
        if priority_within_cap:
            price = word_add_word(base_fee, max_priority_fee)
        else:
            price = max_fee
    base_fee_covered = word_ule(base_fee, price)
    if base_fee_covered:
        priority = word_sub_word(price, base_fee)
    else:
        priority = ZERO_WORD
    return (price, priority)

def check_transaction_validity(tx: Transaction, allowance: TransactionGasAllowanceFields) -> TxValidityFields:
    execution_profile = kernel_environment.k_execution_profile
    profile = execution_profile.protocol
    tx_semantics = tx_type_semantics(tx.tx_type)
    parity = tx_signature_parity(kernel_environment.k_chain_id, tx_semantics.signature, tx.sig_v)
    authenticated = tx_auth_valid(tx.sender, tx.signing_hash, parity, tx.sig_r, tx.sig_s)
    invalid_signature = (not (authenticated))
    if invalid_signature:
        fatal_error(FatalError.InvalidSignature)
    gas_limit = allowance.total
    (eff_gas_price, eff_priority_fee) = eff_gas_price_for(kernel_environment.k_header.base_fee, tx.max_fee, tx.max_priority_fee)
    sender = tx.sender
    input = tx.input_src
    input_len = input.len
    nonce_before = k_get_nonce(sender)
    costs = transaction_costs(profile, tx, gas_limit, kernel_environment.k_header.excess_blob_gas)
    expected_nonce = word_of_account_nonce(nonce_before)
    if ((tx.nonce) != (expected_nonce)):
        fatal_error(FatalError.ExecutionInvalid)
    (sender_deleg, _) = k_deleg_target(sender)
    if tx_semantics.blob:
        if (((int(profile.fork) < int(Cancun))) | (((((tx.blob_hashes.count) == (0))) | (tx.is_create)))):
            fatal_error(FatalError.ExecutionInvalid)
    if (((int(profile.fork) >= int(Prague))) & ((int(gas_limit) < int(costs.calldata_floor)))):
        fatal_error(FatalError.ExecutionInvalid)
    sender_balance = k_get_balance(sender)
    upfront_affordable = word_ule(costs.upfront, sender_balance)
    insufficient_balance = (not (upfront_affordable))
    if insufficient_balance:
        fatal_error(FatalError.ExecutionInvalid)
    sender_code_key = k_code_key(sender)
    valid_sender_code = ((((sender_code_key) == (KECCAK_EMPTY))) | (sender_deleg))
    invalid_sender_code = (not (valid_sender_code))
    if invalid_sender_code:
        fatal_error(FatalError.ExecutionInvalid)
    if (int(allowance.regular) < int(costs.calldata_floor)):
        fatal_error(FatalError.ExecutionInvalid)
    base_fee_affordable = word_ule(kernel_environment.k_header.base_fee, tx.max_fee)
    base_fee_exceeds_cap = (not (base_fee_affordable))
    if base_fee_exceeds_cap:
        fatal_error(FatalError.ExecutionInvalid)
    valid_initcode_size = initcode_size_allowed(input_len)
    invalid_initcode_size = (not (valid_initcode_size))
    if ((tx.is_create) & (invalid_initcode_size)):
        fatal_error(FatalError.ExecutionInvalid)
    valid_priority_fee = word_ule(tx.max_priority_fee, tx.max_fee)
    invalid_priority_fee = (not (valid_priority_fee))
    if invalid_priority_fee:
        fatal_error(FatalError.ExecutionInvalid)
    if (int(profile.fork) < int(tx_semantics.minimum_fork)):
        fatal_error(FatalError.ExecutionInvalid)
    if ((tx_semantics.set_code) & (tx.is_create)):
        fatal_error(FatalError.ExecutionInvalid)
    authorizations = tx.authorizations
    if ((tx_semantics.set_code) & (((authorizations.count) == (0)))):
        fatal_error(FatalError.ExecutionInvalid)
    typed_signature = ((tx_semantics.signature) == (TxSignatureScheme.TypedSignature))
    if ((typed_signature) & (((tx.chain_id) != (kernel_environment.k_chain_id)))):
        fatal_error(FatalError.ExecutionInvalid)
    if ((nonce_before) == ((int((1 << 64)) - 1))):
        fatal_error(FatalError.ExecutionInvalid)
    initial_gas = transaction_initial_gas(allowance, costs.intrinsic_execution, costs.intrinsic_state, costs.calldata_floor)
    return tx_validity_fields(sender, nonce_before, initial_gas, costs.blob_fee, eff_gas_price, eff_priority_fee)

def apply_transaction_upfront_effects(tx: Transaction, v: TxValidity, authorizations: PreparedAuthorizationList) -> TxUpfrontResult:
    execution_profile = kernel_environment.k_execution_profile
    profile = execution_profile.protocol
    initial_gas = v.gas
    if (((int(profile.fork) >= int(Amsterdam))) & (tx.is_create)):
        create_target = k_create_addr(v.sender, v.nonce_before)
        target_exists = k_account_exists(create_target)
        create_target_prestate_empty = (not (target_exists))
    else:
        create_target_prestate_empty = False
    gas_debit = validated_word_product(v.gas_price, initial_gas.admitted_limit)
    k_sub_balance(v.sender, gas_debit)
    has_blob_fee = word_nonzero(v.blob_fee)
    if has_blob_fee:
        k_sub_balance(v.sender, v.blob_fee)
    k_bump_nonce(v.sender)
    prewarm(tx)
    if (int(profile.fork) < int(Amsterdam)):
        authorization_refund_ = process_auth_list(authorizations)
    else:
        authorization_refund_ = 0
    return TxUpfrontResult(authorization_refund=authorization_refund(authorization_refund_), create_target_prestate_empty=create_target_prestate_empty)

def enter_transaction_frame(v: TxValidity) -> tuple[gas, state_gas, state_gas_spill, gas_refund, StackPointer, code_length, code_length]:
    initial_gas = v.gas
    stack = stack_reset()
    return (initial_gas.execution_remaining, initial_gas.state_remaining, STATE_GAS_SPILL_ZERO, GAS_REFUND_ZERO, stack, MEMORY_BASE_ZERO, MEMORY_HEIGHT_ZERO)

